  q('[data-connect]').hidden=accountMode||!!s?.connected;q('[data-disconnect]').hidden=accountMode||!s?.connected;
  input.disabled=!s?.connected||s.busy||!!health?.restoring||!!s.recoverable||!!s.task;if(input.value!==(s?.draft??''))input.value=s?.draft??'';
