  q('[data-check]').disabled=!s?.connected||s.busy;q('[data-recover]').hidden=!s?.recoverable;q('[data-recover]').disabled=!s?.canRetry;
  q('[data-retry]').hidden=!s?.canRetry;q('[data-retry]').disabled=!s?.canRetry||!!health?.restoring;q('[data-recover]').disabled=!s?.canRecover||!!health?.restoring;
